const item = $input.first();
const keys = Object.keys(item.binary || {});
if (keys.length !== 1) throw new Error('Upload exactly one file.');
const sourceId = String(item.json['Upload ID'] || '').trim();
if (!sourceId || sourceId.length > 200) throw new Error('Upload ID must contain 1 to 200 characters.');
return [{json: {direction: 'AP', source_type: 'upload', source_namespace: 'n8n-ap-upload-v1', source_id: sourceId, attachment_id: '0'}, binary: {data: item.binary[keys[0]]}}];

const r = $input.first().json;
const b = r.body || {};
const ok = (r.statusCode === 200 || r.statusCode === 201) && Boolean(b.invoice_id && b.receipt_id);
const text = ok
 ? `Original stored. Invoice ID: ${b.invoice_id}. Receipt ID: ${b.receipt_id}. Repeated delivery: ${b.delivery_duplicate ? 'yes' : 'no'}. Identical content already stored: ${b.content_duplicate ? 'yes' : 'no'}. OCR required by input inspection: ${b.inspection.ocr_required ? 'yes' : 'not established; text quality has not been assessed'}. Status: received. OCR, extraction and review have not run.`
 : `Upload was not accepted (HTTP ${r.statusCode}). ${r.statusCode === 409 ? 'This Upload ID belongs to different file bytes. Use a new ID for a new document.' : 'Check the file and backend response in this execution.'}`;
return [{json: {formSubmittedText: text, intake_success: ok, backend_status: r.statusCode, ...b}}];
